import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function Match({ onGameStart }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [gameStarted, setGameStarted] = useState(false);

  const stompClientRef = useRef(null);
  const pollingRef = useRef(null);
  const timeoutRef = useRef(null);

  const navigate = useNavigate();
  const ALLOWED_FEES = [13, 23, 50];

  // LocalStorage থেকে gameId নিয়ে আগের ম্যাচ চেক
  useEffect(() => {
    const checkExistingMatch = async () => {
      const token = localStorage.getItem("authToken");
      try {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.data?.gameId) {
          setGame(res.data);
          setStatus("⚠️ আগের একটি ম্যাচ পাওয়া গেছে, যুক্ত হচ্ছি...");
        }
      } catch {
        console.warn("❗ আগের ম্যাচ চেক করতে সমস্যা হয়েছে।");
      }
    };
    checkExistingMatch();
  }, []);

  // WebSocket সেটআপ
  useEffect(() => {
    if (!game?.player1 || gameStarted) return;

    const token = localStorage.getItem("authToken");
    const myGameId = localStorage.getItem("myGameId"); // লগইনের সময় সেট করা
    if (!myGameId) return;

    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: (str) => console.log("🔧", str),
      onConnect: () => {
        console.log("🟢 WebSocket connected");

        client.subscribe(`/topic/match/${myGameId}`, (message) => {
          const gameSession = JSON.parse(message.body);
          console.log("📩 ম্যাচ আপডেট:", gameSession);
          setGame(gameSession);

          // যদি ম্যাচ ক্যানসেল হয়
          if (gameSession.status === "CANCELLED") {
            setStatus("❌ ম্যাচ অটো-ক্যানসেল হয়েছে");
            clearInterval(pollingRef.current);
            clearTimeout(timeoutRef.current);
            setLoading(false);
            return;
          }

          // প্লেয়ার সনাক্ত
          if (gameSession.player1 === myGameId) {
            setPlayerId(1);
          } else if (gameSession.player2 === myGameId) {
            setPlayerId(2);
          }

          // ম্যাচ শুরু হলে
          if (gameSession.player1 && gameSession.player2 && !gameStarted) {
            setStatus("🎮 গেম শুরু হয়েছে! রিডাইরেক্ট করা হচ্ছে...");
            setGameStarted(true);

            localStorage.setItem("currentSessionId", gameSession.gameId);
            localStorage.setItem("playerId", playerId);
            localStorage.setItem("entryFee", entryFee);

            onGameStart({ gameId: gameSession.gameId, playerId, entryFee });

            clearInterval(pollingRef.current);
            clearTimeout(timeoutRef.current);

            setTimeout(() => {
              navigate("/game");
            }, 1000);
          }
        });

        // WebSocket হলে পোলিং বন্ধ
        if (pollingRef.current) clearInterval(pollingRef.current);
      },
      onStompError: (frame) => {
        console.error("❌ STOMP Error:", frame);
        setStatus("❌ WebSocket সমস্যা হয়েছে!");
      },
    });

    client.activate();
    stompClientRef.current = client;

    return () => {
      if (client) client.deactivate();
      if (pollingRef.current) clearInterval(pollingRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [game?.player1, gameStarted, entryFee, onGameStart, navigate, playerId]);

  // ম্যাচ রিকোয়েস্ট
  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(entryFee)) {
      setStatus("❌ ভুল এন্ট্রি ফি, 13, 23, 50 থেকে সিলেক্ট করো।");
      return;
    }

    setLoading(true);
    setStatus("🔍 প্রতিপক্ষ খুঁজছি...");
    const token = localStorage.getItem("authToken");

    try {
      await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        { headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" } }
      );

      // ৩ সেকেন্ড অন্তর পোলিং
      pollingRef.current = setInterval(async () => {
        try {
          const res = await axios.get("http://localhost:8080/api/match/status", {
            headers: { Authorization: `Bearer ${token}` },
          });
          if (res.data?.gameId) {
            clearInterval(pollingRef.current);
            clearTimeout(timeoutRef.current);
            setGame(res.data);
            setStatus("🎉 প্রতিপক্ষ পাওয়া গেছে!");
          }
        } catch (err) {
          console.error("Polling error:", err);
        }
      }, 3000);

      // ৩০ মিনিট টাইমআউট
      timeoutRef.current = setTimeout(() => {
        clearInterval(pollingRef.current);
        setStatus("⏳ ৩০ মিনিটে প্রতিপক্ষ পাওয়া যায়নি, আবার চেষ্টা করুন।");
        setLoading(false);
        if (stompClientRef.current) stompClientRef.current.deactivate();
      }, 30 * 60 * 1000);
    } catch (err) {
      setStatus("⚠️ সার্ভার সমস্যা: " + (err.response?.data?.error || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-lg mx-auto mt-12 p-6 bg-white border rounded-xl shadow-lg">
      <h2 className="text-2xl font-bold text-center text-indigo-700 mb-6">🎲 লুডু ম্যাচ শুরু</h2>

      <div className="mb-5">
        <label className="block text-sm font-medium text-gray-700 mb-2">এন্ট্রি ফি সিলেক্ট করুন</label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full px-4 py-2 border rounded-md shadow-sm focus:outline-none"
          disabled={loading}
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        disabled={loading}
        className={`w-full py-2 px-4 text-white font-semibold rounded-md ${
          loading ? "bg-gray-400" : "bg-indigo-600 hover:bg-indigo-700"
        }`}
      >
        {loading ? "⏳ খোঁজা হচ্ছে..." : "🔍 প্রতিপক্ষ খুঁজুন"}
      </button>

      {status && (
        <div className="mt-6 text-sm text-center text-gray-700">
          <strong>স্ট্যাটাস:</strong> {status}
        </div>
      )}
    </div>
  );
}
